import axios from "axios";

// Socket connection
//localStorage.debug = "socket.io-client:socket";
const socket = io();

// DOM elements for screens
const lobbyScreen = document.getElementById("lobbyScreen");
const gameScreen = document.getElementById("gameScreen");

// Form elements
const userForm = document.getElementById("gameForm");
const modeInputs = document.querySelectorAll("input[name='mode']");
const codeField = document.getElementById("codeField");

// Show code field only when "Join Game" is selected
modeInputs.forEach((radio) => {
  radio.addEventListener("change", () => {
    if (radio.value === "join" && radio.checked) {
      codeField.style.display = "block";
    } else {
      codeField.style.display = "none";
    }
  });
});

// Submit form (Host or Join game)
if (userForm) {
  userForm.addEventListener("submit", async (e) => {
    e.preventDefault();

    const formData = new FormData(e.target);
    const data = Object.fromEntries(formData.entries());
    console.log(data)
    try {
      const res = await axios({
        method: "POST",
        url: "http://127.0.0.1:8100/api/v1/user",
        data,
      });

      console.log("User created:", res.data);

      if (res.data.status === "success") {
        // ✅ Switch UI without reloading
        lobbyScreen.style.display = "none";
        gameScreen.style.display = "block";

        // ✅ Join the socket.io game
        socket.emit("join_game", { event: "join", data: res.data });
      }
    } catch (err) {
      console.error("Error joining/hosting:", err);
    }
  });
}
